effect.shader:
const int MAXIMO_DE_ARRANHOES = 12;

float hash1(float x) {
    return fract(sin(x * 127.1 + float(seed) * 13.7) * 43758.5453);
}

float hash2(vec2 c) {
    return fract(sin(dot(c, vec2(127.1, 311.7)) + float(seed) * 13.7) * 43758.5453);
}

/** A matriz clássica de sépia (Microsoft Office / IE "sepia" filter). */
vec3 sepia(vec3 c) {
    float r = dot(c, vec3(0.393, 0.769, 0.189));
    float g = dot(c, vec3(0.349, 0.686, 0.168));
    float b = dot(c, vec3(0.272, 0.534, 0.131));
    return vec3(r, g, b);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    // 1. Sépia
    vec3 cor = mix(original.rgb, sepia(original.rgb), sepiaMix);

    // 2. Grão: hash do pixel + tempo (o tempo faz o grão dançar).
    float grao = hash2(acScreenNorm * 1000.0 + vec2(acTime * 60.0)) - 0.5;
    cor += vec3(grao) * grainStrength;

    // 3. Cintilação: brilho global oscila devagar.
    float bruxuleio = 1.0 + (hash1(floor(acTime * 12.0)) - 0.5) * flickerStrength * 2.0;
    cor *= bruxuleio;

    // 4. Arranhões verticais: cada "quadro do projetor" (acTime arredondado por scratchFreq)
    //    sorteia N posições; se o pixel está perto de alguma delas, risca.
    int n = clamp(int(scratchCount + 0.5), 0, MAXIMO_DE_ARRANHOES);
    float quadro = floor(acTime * scratchFreq);
    float traco = 0.0;
    for (int k = 0; k < MAXIMO_DE_ARRANHOES; k++) {
        if (k >= n) break;
        float x = hash1(quadro * 97.0 + float(k) * 13.1);
        float largura = 0.0005 + 0.0015 * hash1(quadro * 7.0 + float(k) * 3.3);
        float distancia = abs(acScreenNorm.x - x);
        traco = max(traco, 1.0 - smoothstep(0.0, largura, distancia));
    }
    cor = mix(cor, vec3(1.0), traco * 0.7);

    cor = clamp(cor, 0.0, 1.0);
    fragColor = vec4(cor, original.a);
}
